/** Independent SSR geometry reader. IDs locate elements, coordinates determine meaning. */
import assert from'node:assert/strict';import facts from'./legacy-2017-pm2-facts.json';
const decode=(s:string)=>s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#x27;/g,"'");
const attr=(s:string,k:string)=>{const m=s.match(new RegExp('(?:^|\\s)'+k+'="([^"]*)"'));assert(m,k);return decode(m[1]);};const tagged=(s:string,tag:string,k:string)=>[...s.matchAll(new RegExp('<'+tag+'\\b([^>]*\\b'+k+'="[^"]*"[^>]*)>([\\s\\S]*?)<\\/'+tag+'>|<'+tag+'\\b([^>]*\\b'+k+'="[^"]*"[^>]*)\\/?>','g'))].map(m=>({a:m[1]??m[3],text:decode((m[2]??'').replace(/<[^>]*>/g,''))}));
const points=(s:string)=>s.split(' ').map(x=>x.split(',').map(Number));const centers:Record<string,string>={'850,370':'top','910,425':'upperRight','910,535':'lowerRight','850,590':'bottom','790,535':'lowerLeft','790,425':'upperLeft','850,480':'middle','940,590':'decimalPoint'};
const polygonPoints:Record<string,string>={'7':'800,370 810,360 890,360 900,370 890,380 810,380','6':'910,390 920,400 920,450 910,460 900,450 900,400','5':'910,500 920,510 920,560 910,570 900,560 900,510','4':'800,590 810,580 890,580 900,590 890,600 810,600','3':'790,500 800,510 800,560 790,570 780,560 780,510','2':'790,390 800,400 800,450 790,460 780,450 780,400','1':'800,480 810,470 890,470 900,480 890,490 810,490'};
const wirePoints=['610,344 650,344 650,310 850,310 850,370','610,372 680,372 680,328 970,328 970,425 910,425','610,400 710,400 710,346 1000,346 1000,535 910,535','610,428 650,428 650,635 850,635 850,590','610,456 680,456 680,535 790,535','610,484 650,484 650,425 790,425','610,512 720,512 720,480 850,480','610,540 630,540 630,660 940,660 940,590'];
function litLocations(svg:string){const ps=tagged(svg,'polygon','data-led-bit');assert.equal(ps.length,7);const lit=new Set<string>();for(const p of ps){const pt=points(attr(p.a,'points')),x=(Math.min(...pt.map(p=>p[0]))+Math.max(...pt.map(p=>p[0])))/2,y=(Math.min(...pt.map(p=>p[1]))+Math.max(...pt.map(p=>p[1])))/2,name=centers[[x,y].join(',')];assert(name);const style=attr(p.a,'style');assert(style==='fill:currentColor'||style==='fill:var(--surface)');if(style==='fill:currentColor')lit.add(name);}return lit;}
/** Decode by actual wire source y and destination region, independently of wire IDs. */
export function decodeLegacy2017Pm2WiredDigit(system:string,digit:string){const lit=litLocations(digit),labels=tagged(system,'text','data-port-bit');assert.equal(labels.length,16);const ys=new Map(labels.map(t=>[Number(attr(t.a,'y')),Number(t.text.replace('ビット ',''))]));const wires=tagged(system,'polyline','data-wire-bit');assert.equal(wires.length,8);let value=0;for(const w of wires){const ps=points(attr(w.a,'points')),bit=ys.get(ps[0][1]),pos=centers[ps.at(-1)!.join(',')];assert(bit!==undefined&&bit>=0&&bit<=7&&pos);if(lit.has(pos))value+=2**bit;}return value.toString(16).toUpperCase().padStart(2,'0');}

/** Preserve the original visible legend heading and its two state keys. */
function readLegendContract(svg:string){
 const headings=tagged(svg,'text','data-legend-heading');assert.equal(headings.length,1,'one visible legend heading');
 const heading=headings[0];assert.equal(heading.text,'凡例');assert.equal(attr(heading.a,'x'),'780');assert.equal(attr(heading.a,'y'),'710');
 const view=attr(tagged(svg,'svg','viewBox')[0].a,'viewBox').split(' ').map(Number);assert.deepEqual(view,[0,0,1100,860]);
 const polygons=tagged(svg,'polygon','data-legend'),dots=tagged(svg,'circle','data-legend-dot');
 assert.deepEqual(polygons.map(p=>[attr(p.a,'data-legend'),attr(p.a,'points'),attr(p.a,'style')]),[
  ['on','780,755 790,745 825,745 835,755 825,765 790,765','fill:currentColor'],
  ['off','780,790 790,780 825,780 835,790 825,800 790,800','fill:var(--surface)']]);
 assert.deepEqual(dots.map(p=>[attr(p.a,'data-legend-dot'),attr(p.a,'cx'),attr(p.a,'cy'),attr(p.a,'r'),attr(p.a,'style')]),[
  ['on','850','755','7','fill:currentColor'],['off','850','790','7','fill:var(--surface)']]);
 const texts=tagged(svg,'text','x');for(const[label,y]of[['点灯状態',755],['消灯状態',790]]as const){const ts=texts.filter(t=>t.text===label);assert.equal(ts.length,1);assert.equal(attr(ts[0].a,'x'),'880');assert.equal(Number(attr(ts[0].a,'y')),y);}
 const maxWireY=Math.max(...wirePoints.flatMap(s=>points(s).map(p=>p[1]))),hy=Number(attr(heading.a,'y'));
 assert(hy>=maxWireY+40&&hy<=755-30,'heading separated from wires and first state key');
 assert(Number(attr(heading.a,'x'))>=0&&Number(attr(heading.a,'x'))+80<view[2]&&hy+30<view[3],'legend heading within SVG');
}

export function readLegacy2017Pm2Svg(svg:string,variant:number,part:number){assert(variant>=0&&variant<3&&part>=0&&part<5);const desc=decode(svg.match(/<desc[^>]*>([\s\S]*?)<\/desc>/)![1]);assert(desc.length>20);assert(!/<script\b/.test(svg));
 if(part===0){assert.equal(tagged(svg,'rect','data-notice-frame').length,1);const c=tagged(svg,'circle','data-selection-circle')[0];assert.equal(attr(c.a,'cx'),'380');assert.equal(attr(c.a,'cy'),'85');assert.equal(attr(c.a,'r'),'18');assert.equal(tagged(svg,'text','x').map(t=>t.text).join(''),facts.source.selectionNotice);assert(desc.includes(facts.source.selectionNotice));}
 if(part===1||part===2){assert.deepEqual(tagged(svg,'rect','data-led-frame').map(t=>['x','y','width','height','fill'].map(k=>attr(t.a,k))),[['765','345','190','275','none']]);const ps=tagged(svg,'polygon','data-led-bit');assert.equal(ps.length,7);for(const p of ps)assert.equal(attr(p.a,'points'),polygonPoints[attr(p.a,'data-led-bit')]);const dot=tagged(svg,'circle','data-led-bit')[0];assert.equal(attr(dot.a,'cx'),'940');assert.equal(attr(dot.a,'cy'),'590');assert.equal(attr(dot.a,'r'),'10');assert.equal(attr(dot.a,'style'),'fill:var(--surface)');const digit=part===1?2:[6,4,3][variant],expected=facts.figures.figure2.digitSegments[String(digit)as keyof typeof facts.figures.figure2.digitSegments];assert.deepEqual([...litLocations(svg)].sort(),[...expected].sort());}
 if(part===1){readLegendContract(svg);const ws=tagged(svg,'polyline','data-wire-bit');assert.deepEqual(ws.map(w=>attr(w.a,'points')),wirePoints);for(const w of ws){const ps=points(attr(w.a,'points'));for(let i=1;i<ps.length;i++)assert(ps[i-1][0]===ps[i][0]||ps[i-1][1]===ps[i][1]);}const labels=tagged(svg,'text','data-port-bit');assert.deepEqual(labels.map(t=>t.text),Array.from({length:16},(_,i)=>i===0?'ビット 15':String(15-i)));labels.forEach((t,i)=>{assert.equal(attr(t.a,'x'),'590');assert.equal(Number(attr(t.a,'y')),120+28*i);assert.equal(attr(t.a,'text-anchor'),'end');});assert.equal(tagged(svg,'circle','data-bus-dot').length,4);for(const dot of tagged(svg,'circle','data-bus-dot'))assert.equal(attr(dot.a,'style'),'fill:currentColor');assert.deepEqual(tagged(svg,'rect','data-device').map(t=>[attr(t.a,'data-device'),...['x','y','width','height'].map(k=>Number(attr(t.a,k)))]),[['CPU',35,80,150,70],['タイマ',35,220,210,100],['温度検出器',35,420,170,70],['A/D変換器',35,555,170,70]]);assert.deepEqual(tagged(svg,'line','data-bus').map(t=>['x1','y1','x2','y2'].map(k=>Number(attr(t.a,k)))),[[300,50,300,675]]);assert.deepEqual(tagged(svg,'line','data-bus-link').map(t=>['x1','y1','x2','y2'].map(k=>Number(attr(t.a,k)))),[[185,115,300,115],[245,270,300,270],[300,530,450,530],[205,590,300,590]]);assert.deepEqual(tagged(svg,'circle','data-bus-dot').map(t=>['cx','cy','r'].map(k=>Number(attr(t.a,k)))),[[300,115,4],[300,270,4],[300,530,4],[300,590,4]]);assert.deepEqual(tagged(svg,'rect','data-port').map(t=>['x','y','width','height'].map(k=>Number(attr(t.a,k)))),[[450,85,160,590]]);const sensor=tagged(svg,'line','data-sensor-arrow')[0];assert.deepEqual(['x1','y1','x2','y2'].map(k=>attr(sensor.a,k)),['120','490','120','555']);assert.equal(tagged(svg,'polygon','data-legend').length,2);assert.equal(tagged(svg,'circle','data-legend-dot').length,2);}
 if(part===3){const headings=tagged(svg,'text','data-table-heading');assert.deepEqual(headings.map(t=>t.text),['機器','I/Oポート番号','動作概要']);const lines=tagged(svg,'line','data-table-row');assert.deepEqual(lines.map(t=>['x1','y1','x2','y2'].map(k=>Number(attr(t.a,k)))),[[10,194,1210,194],[300,298,1210,298],[300,402,1210,402],[170,506,1210,506]]);const ops=tagged(svg,'text','data-operation-row');const table=facts.source.pages[2].blocks.find(b=>b.id==='table2')!;assert('rows'in table&&table.rows);for(let i=0;i<5;i++){const ts=ops.filter(t=>Number(attr(t.a,'data-operation-row'))===i);assert.equal(ts.map(t=>t.text).join(''),table.rows[i][2]);assert(desc.includes(table.rows[i][2]));ts.forEach((t,j)=>{assert.equal(attr(t.a,'x'),'320');assert.equal(Number(attr(t.a,'y')),120+i*104+j*30);});}assert.deepEqual(tagged(svg,'text','data-table-device').map(t=>[t.text,attr(t.a,'x'),attr(t.a,'y')]),[['LED','30','120'],['A/D変換器','25','402']]);assert.deepEqual(tagged(svg,'text','data-table-port').map(t=>[t.text,attr(t.a,'x'),attr(t.a,'y')]),[['1','220','120'],['2','220','350'],['3','220','558']]);}
 if(part===4){assert(desc.includes('GR←α'));assert(desc.includes('空欄d'));assert(desc.includes('空欄e'));const nodes=tagged(svg,'rect','data-flow-node'),diamond=tagged(svg,'polygon','data-flow-node');assert.equal(nodes.length,9);assert.equal(diamond.length,1);assert.equal(attr(diamond[0].a,'points'),'300,440 390,480 300,520 210,480');const expected=[['start',20],['gr1',140],['out2',250],['in2',350],['in3',580],['convert',690],['gra',790],['e',890],['end',990]];assert.deepEqual(nodes.map(t=>[attr(t.a,'data-flow-node'),Number(attr(t.a,'y'))]),expected);nodes.forEach(t=>{assert.equal(attr(t.a,'x'),'210');assert.equal(attr(t.a,'width'),'180');assert.equal(attr(t.a,'height'),'50');if(['start','end'].includes(attr(t.a,'data-flow-node')))assert.equal(attr(t.a,'rx'),'25');});const main=tagged(svg,'line','data-flow-main');assert.deepEqual(main.map(t=>['x1','y1','x2','y2'].map(k=>Number(attr(t.a,k)))),[[300,70,300,140],[300,190,300,250],[300,300,300,350],[300,400,300,440],[300,520,300,580],[300,630,300,690],[300,740,300,790],[300,840,300,890],[300,940,300,990]]);const ret=tagged(svg,'polyline','data-flow-return')[0];assert.equal(attr(ret.a,'points'),'210,480 90,480 90,325 300,325');const reference=attr(ret.a,'marker-end').match(/^url\(#([^\)]+)\)$/)![1],marker=[...svg.matchAll(/<marker\b([^>]*)>([\s\S]*?)<\/marker>/g)].find(m=>attr(m[1],'id')===reference);assert(marker);assert.equal(attr(marker[1],'orient'),'auto');assert.equal(attr(marker[1],'refX'),'9');assert(marker[2].includes('d="M1 1 L9 5 L1 9"'));assert(marker[2].includes('stroke="currentColor"'));const links=tagged(svg,'line','data-comment-link');assert.deepEqual(links.map(t=>[attr(t.a,'data-comment-link'),...['x1','y1','x2','y2'].map(k=>Number(attr(t.a,k)))]),[['start',390,275,435,275],['convert',390,715,435,715]]);for(const t of links)assert.equal(attr(t.a,'stroke-dasharray'),'7 5');assert.deepEqual(tagged(svg,'path','data-comment-bracket').map(t=>[attr(t.a,'data-comment-bracket'),attr(t.a,'d')]),[['start','M450 250 H435 V300 H450'],['convert','M450 685 H435 V745 H450']]);const blanks=tagged(svg,'rect','data-blank');assert.deepEqual(blanks.map(t=>[attr(t.a,'data-blank'),...['x','y','width','height'].map(k=>Number(attr(t.a,k)))]),[['d',267,461,66,37],['e',245,898,110,34]]);const texts=tagged(svg,'text','x');const position=(label:string,x:number,y:number)=>{const ts=texts.filter(t=>t.text===label);assert.equal(ts.length,1,label);assert.equal(Number(attr(ts[0].a,'x')),x,label);assert.equal(Number(attr(ts[0].a,'y')),y,label);};for(const[label,x,y]of[['Yes',130,458],['No',320,550],['d',291,480],['e',292,915],['GR←α',235,815],['A/D変換開始',455,275],['A/D変換器の出力値を',455,705],['形状データαに変換',455,735]]as const)position(label,x,y);for(const blank of blanks){const name=attr(blank.a,'data-blank'),x=Number(attr(blank.a,'x')),y=Number(attr(blank.a,'y')),w=Number(attr(blank.a,'width')),h=Number(attr(blank.a,'height'));if(name==='d'){for(const[cx,cy]of[[x,y],[x+w,y],[x,y+h],[x+w,y+h]])assert(Math.abs(cx-300)/90+Math.abs(cy-480)/40<1,'d must be inside diamond');}else assert(x>210&&x+w<390&&y>890&&y+h<940,'e must be inside final process');const letter=texts.find(t=>t.text===name)!;assert(Number(attr(letter.a,'x'))>x&&Number(attr(letter.a,'x'))+16<x+w);assert(Number(attr(letter.a,'y'))-13>y&&Number(attr(letter.a,'y'))+13<y+h);} const visible=tagged(svg,'text','x').map(t=>t.text).join('');for(const t of['開始','GR←1','OUTPUT 2','INPUT 2','Yes','No','INPUT 3','変換処理','GR←α','d','e','終了','A/D変換開始','A/D変換器の出力値を','形状データαに変換'])assert(visible.includes(t),t);assert(!visible.includes('GR＝0'));assert(!visible.includes('OUTPUT 1'));}
 return{variant,part,desc};
}
